<?php
namespace App\Http\Controllers;
use App\Models\User;
use App\Services\Portal\Access;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\{Auth,DB,Hash,Crypt};
use Illuminate\Validation\Rule;
class PortalController extends Controller {
 public function loginPage(){return response()->view('portal.login')->header('Cache-Control','no-store, private');}
 public function loginSession(Request $r){return response()->json(['token'=>$r->session()->token()])->header('Cache-Control','no-store, private')->header('Vary','Cookie');}
 public function login(Request $r,Access $a){$d=$r->validate(['email'=>'required|email','password'=>'required|string|max:300']);$d['email']=strtolower(trim($d['email']));if(!Auth::attempt($d+['voice_enabled'=>true]))return back()->withErrors(['login'=>'E-mail ou senha inválidos.'])->onlyInput('email');$r->session()->regenerate();$r->session()->put('voice_auth_version',(int)$r->user()->voice_auth_version);$a->audit('login',$r->user()->id,null);$members=DB::table('portal_memberships')->join('portal_tenants','portal_tenants.id','=','tenant_id')->where('user_id',$r->user()->id)->where('active',true)->where('status','active')->get(['slug']);if(count($members)===1&&!$a->operator($r->user()->id))return redirect('/t/'.$members[0]->slug);return redirect('/companies');}
 public function logout(Request $r){$r->user()->increment('voice_auth_version');Auth::logout();$r->session()->invalidate();$r->session()->regenerateToken();return redirect('/login');}
 public function companies(Request $r,Access $a){$operator=$a->operator($r->user()->id);$tenants=$operator?DB::table('portal_tenants')->orderBy('name')->get():DB::table('portal_tenants')->join('portal_memberships','portal_tenants.id','=','tenant_id')->where('user_id',$r->user()->id)->where('active',true)->orderBy('name')->get(['portal_tenants.*','role']);if($operator)foreach($tenants as $t)$t->role='platform';return view('portal.companies',compact('tenants','operator'));}
 public function launch(Request $r,string $slug,Access $a){$d=$r->validate(['section'=>'nullable|in:overview,supervision,queues,team,journeys,conversations,inbound']);$t=DB::table('portal_tenants')->where('slug',$slug)->firstOrFail();$identity=$a->identity($t->id,$r->user()->id);abort_unless($t->url,409,'Ambiente ainda em preparação.');if($identity['platform_admin'])$a->audit('platform.operation_opened',$r->user()->id,$t->id,['section'=>$d['section']??'overview']);return redirect()->away($t->url.'/discai/sso/start'.(!empty($d['section'])?'?section='.$d['section']:''));}
 public function authorizeTenant(Request $r,string $slug,Access $a){$d=$r->validate(['state'=>'required|regex:/^[a-f0-9]{64}$/D']);$t=DB::table('portal_tenants')->where('slug',$slug)->firstOrFail();$a->identity($t->id,$r->user()->id);$token=bin2hex(random_bytes(32));DB::table('portal_grants')->insert(['tenant_id'=>$t->id,'user_id'=>$r->user()->id,'token_hash'=>hash('sha256',$token),'state_hash'=>hash('sha256',$d['state']),'expires_at'=>now()->addSeconds(60),'created_at'=>now(),'updated_at'=>now()]);$a->audit('sso.issued',$r->user()->id,$t->id);return redirect()->away($t->url.'/discai/sso/complete?'.http_build_query(['code'=>$token,'state'=>$d['state']]))->header('Referrer-Policy','no-referrer')->header('Cache-Control','no-store');}
 public function redeem(Request $r,Access $a){$t=$a->authenticateTenant($r);$d=$r->validate(['code'=>'required|regex:/^[a-f0-9]{64}$/D','state'=>'required|regex:/^[a-f0-9]{64}$/D']);return DB::transaction(function()use($t,$d,$a){$g=DB::table('portal_grants')->where('token_hash',hash('sha256',$d['code']))->where('tenant_id',$t->id)->lockForUpdate()->first();abort_unless($g&&!$g->used_at&&$g->expires_at>now()&&hash_equals($g->state_hash,hash('sha256',$d['state'])),403);$identity=$a->identity($t->id,$g->user_id);abort_unless(DB::table('portal_grants')->where('id',$g->id)->whereNull('used_at')->update(['used_at'=>now()])===1,403);$a->audit('sso.redeemed',$g->user_id,$t->id);return $identity;});}
 public function check(Request $r,Access $a){$t=$a->authenticateTenant($r);$d=$r->validate(['user_id'=>'required|integer|min:1']);return $a->identity($t->id,$d['user_id']);}
 private function admin(Request $r,Access $a):void {abort_unless($a->operator($r->user()->id),403);}
 public function administration(Request $r,Access $a){$this->admin($r,$a);$tenants=DB::table('portal_tenants')->orderBy('name')->get();$audit=DB::table('portal_audit')->leftJoin('users','users.id','=','portal_audit.user_id')->latest('portal_audit.id')->limit(30)->get(['portal_audit.*','users.name']);return view('portal.admin',compact('tenants','audit'));}
 public function createTenant(Request $r,Access $a){$this->admin($r,$a);$d=$r->validate(['name'=>'required|string|max:160','slug'=>['required','regex:/^[a-z][a-z0-9-]{2,38}[a-z0-9]$/D',Rule::notIn(['www','app','admin','api','mail','login','support']),Rule::unique('portal_tenants','slug')],'plan'=>'required|string|max:80','seats'=>'required|integer|between:1,100','channels'=>'required|integer|between:1,10','storage_mb'=>'required|integer|between:128,102400']);$id=DB::table('portal_tenants')->insertGetId($d+['status'=>'provisioning','created_at'=>now(),'updated_at'=>now()]);$a->audit('tenant.created',$r->user()->id,$id,['limits'=>array_intersect_key($d,array_flip(['seats','channels','storage_mb']))]);return redirect('/administration/'.$id)->with('notice','Empresa criada. O ambiente será preparado antes de liberar o acesso.');}
 private function manageTenant(Request $r,int $id,Access $a):void {abort_unless($a->manages($id,$r->user()->id),403);}
 public function tenant(Request $r,int $id,Access $a){$this->manageTenant($r,$id,$a);$operator=$a->operator($r->user()->id);$tenant=DB::table('portal_tenants')->find($id);abort_unless($tenant,404);$roles=['admin'=>'Administrador','supervisor'=>'Supervisor','agent'=>'Atendente'];$mailReady=app(\App\Services\Portal\Invitations::class)->mailReady();$members=DB::table('portal_memberships')->join('users','users.id','=','user_id')->where('tenant_id',$id)->get(['portal_memberships.*','users.name','users.email']);$invites=DB::table('portal_invitations')->where('tenant_id',$id)->whereNull('accepted_at')->where('expires_at','>',now())->get(['id','email','role','expires_at']);return view('portal.tenant',compact('tenant','members','invites','operator','roles','mailReady'));}
 public function updateTenant(Request $r,int $id,Access $a){$this->admin($r,$a);$d=$r->validate(['name'=>'required|string|max:160','plan'=>'required|string|max:80','seats'=>'required|integer|between:1,100','channels'=>'required|integer|between:1,10','storage_mb'=>'required|integer|between:128,102400','status'=>'required|in:active,suspended']);$t=DB::table('portal_tenants')->find($id);abort_unless($t,404);abort_unless(in_array($t->status,['active','suspended']),409,'Aguarde o provisionamento.');abort_if(DB::table('portal_memberships')->where('tenant_id',$id)->where('active',true)->count()>$d['seats'],422,'O limite não pode ser inferior à equipe ativa.');DB::table('portal_tenants')->where('id',$id)->update($d+['updated_at'=>now()]);$a->audit('tenant.updated',$r->user()->id,$id,$d);return back()->with('notice','Configuração salva.');}
 public function invite(Request $r,int $id,Access $a){$this->manageTenant($r,$id,$a);$d=$r->validate(['email'=>'required|email|max:200','role'=>'required|in:admin,supervisor,agent','delivery'=>'sometimes|in:link,email']);$service=app(\App\Services\Portal\Invitations::class);$result=$service->create($id,$r->user()->id,strtolower(trim($d['email'])),$d['role'],$d['delivery']??'link');return back()->with('invitation',$result['url'])->with('notice',$result['message']);}
 public function revokeInvitation(Request $r,int $id,int $invitation,Access $a){$this->manageTenant($r,$id,$a);$i=DB::table('portal_invitations')->where('tenant_id',$id)->where('id',$invitation)->whereNull('accepted_at')->firstOrFail();abort_unless($a->assigns($id,$r->user()->id,$i->role),403);DB::table('portal_invitations')->where('id',$i->id)->update(['expires_at'=>now()]);$a->audit('invitation.revoked',$r->user()->id,$id,['invitation'=>$i->id]);return back()->with('notice','Convite cancelado.');}
 public function invitation(string $token){abort_unless(preg_match('/^[a-f0-9]{64}$/D',$token),404);$invite=DB::table('portal_invitations')->where('token_hash',hash('sha256',$token))->whereNull('accepted_at')->where('expires_at','>',now())->first();abort_unless($invite,410,'Convite expirado ou já utilizado.');$exists=User::where('email',$invite->email)->exists();return view('portal.invite',compact('invite','exists','token'));}
 public function accept(Request $r,string $token,Access $a){$r->validate(['password'=>'required|string|max:200','name'=>'required|string|max:160']);$uid=DB::transaction(function()use($r,$token,$a){$i=DB::table('portal_invitations')->where('token_hash',hash('sha256',$token))->lockForUpdate()->first();abort_unless($i&&!$i->accepted_at&&$i->expires_at>now(),410);$t=DB::table('portal_tenants')->where('id',$i->tenant_id)->lockForUpdate()->first();abort_unless($t&&$t->status!=='suspended',403);if($i->created_by){$issuer=User::find($i->created_by);abort_unless($issuer&&$issuer->voice_enabled&&$a->assigns($t->id,$issuer->id,$i->role),403,'O responsável pelo convite não possui mais esta permissão.');}$u=User::where('email',$i->email)->first();if($u)abort_if($a->member($t->id,$u->id),409,'Você já possui acesso a esta empresa. Entre com sua conta.');if($u){abort_unless($u->voice_enabled&&Hash::check($r->password,$u->password),422,'Use sua senha atual para aceitar o convite.');}else{\Illuminate\Support\Facades\Validator::make($r->only('password'),['password'=>'required|string|min:12|max:200'])->validate();$u=User::create(['name'=>$r->name,'email'=>$i->email,'password'=>$r->password]);}abort_if(!$a->member($t->id,$u->id)&&DB::table('portal_memberships')->where('tenant_id',$t->id)->where('active',true)->count()>=$t->seats,422,'Limite de usuários atingido.');DB::table('portal_memberships')->updateOrInsert(['tenant_id'=>$t->id,'user_id'=>$u->id],['role'=>$i->role,'active'=>true,'created_at'=>now(),'updated_at'=>now()]);DB::table('portal_invitations')->where('id',$i->id)->update(['accepted_at'=>now()]);$a->audit('invitation.accepted',$u->id,$t->id);return $u->id;});Auth::loginUsingId($uid);$r->session()->regenerate();$r->session()->put('voice_auth_version',(int)$r->user()->voice_auth_version);return redirect('/companies');}
 public function membership(Request $r,int $id,int $member,Access $a){$this->manageTenant($r,$id,$a);$d=$r->validate(['role'=>'required|in:admin,supervisor,agent','active'=>'required|boolean']);DB::transaction(function()use($id,$member,$d,$r,$a){$t=DB::table('portal_tenants')->where('id',$id)->lockForUpdate()->first();$m=DB::table('portal_memberships')->where('tenant_id',$id)->where('id',$member)->first();abort_unless($t&&$m,404);abort_unless($a->assigns($id,$r->user()->id,$m->role)&&$a->assigns($id,$r->user()->id,$d['role']),403,'Somente administradores podem gerenciar os acessos desta empresa.');abort_if($m->user_id===$r->user()->id&&(!$d['active']||$d['role']!==$m->role),422,'Peça a outro administrador para alterar seu acesso.');abort_if($m->role==='admin'&&$m->active&&(!$d['active']||$d['role']!=='admin')&&DB::table('portal_memberships')->where('tenant_id',$id)->where('role','admin')->where('active',true)->count()<=1,422,'Mantenha pelo menos um administrador ativo.');abort_if($d['active']&&!$m->active&&DB::table('portal_memberships')->where('tenant_id',$id)->where('active',true)->count()>=$t->seats,422,'Limite de usuários atingido.');DB::table('portal_memberships')->where('id',$m->id)->update($d+['updated_at'=>now()]);});$a->audit('membership.updated',$r->user()->id,$id,['member'=>$member]+$d);return back()->with('notice','Acesso atualizado.');}
 public function password(Request $r,Access $a){$d=$r->validate(['current_password'=>'required|string','password'=>'required|string|min:12|max:200|confirmed']);abort_unless(Hash::check($d['current_password'],$r->user()->password),422,'Senha atual incorreta.');$r->user()->forceFill(['password'=>$d['password'],'voice_auth_version'=>$r->user()->voice_auth_version+1])->save();$r->session()->put('voice_auth_version',(int)$r->user()->voice_auth_version);$r->session()->regenerate();$a->audit('password.changed',$r->user()->id,null);return back()->with('notice','Senha atualizada. As demais sessões serão encerradas.');}
}
